import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

export default function Review() {
  const [form, setForm] = useState({
    name: "",
    rating: 0,
    message: "",
  });

  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  const submitReview = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const res = await fetch("http://localhost:5001/api/reviews", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });

      if (!res.ok) throw new Error("Failed");

      setSuccess(true);
      setForm({ name: "", rating: 0, message: "" });

      setTimeout(() => setSuccess(false), 4000);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <section className="bg-black text-white py-32 px-6 relative overflow-hidden">
      {/* DECORATIVE GLOW */}
      <div className="absolute -top-40 -left-40 w-96 h-96 bg-[#e9b21a]/10 blur-[120px]" />
      <div className="absolute -bottom-40 -right-40 w-96 h-96 bg-[#e9b21a]/10 blur-[120px]" />

      <div className="relative max-w-5xl mx-auto">
        {/* HEADING */}
        <motion.div
          initial={{ opacity: 0, y: 40 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="text-center mb-20"
        >
          <h2 className="text-4xl md:text-5xl font-bold">
            Your <span className="text-[#e9b21a]">Review</span> Matters
          </h2>
          <p className="mt-6 text-gray-400 max-w-2xl mx-auto">
            Every transformation starts with trust. Share your experience and
            help others take the first step toward a healthier life.
          </p>
        </motion.div>

        {/* FORM CONTAINER */}
        <motion.div
          initial={{ opacity: 0, y: 50 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="grid md:grid-cols-2 gap-14 items-center"
        >
          {/* LEFT TEXT */}
          <div className="space-y-6">
            <h3 className="text-3xl font-semibold leading-snug">
              Train. Transform. <br />
              <span className="text-[#e9b21a]">Tell Your Story.</span>
            </h3>

            <p className="text-gray-400">
              Your honest feedback motivates our trainers and helps us maintain
              the Bodyzeal Fitworks standard of excellence.
            </p>

            <ul className="text-sm text-gray-300 space-y-2">
              <li>✔ Helps new members choose confidently</li>
              <li>✔ Improves training & service quality</li>
              <li>✔ Strengthens our fitness community</li>
            </ul>
          </div>

          {/* REVIEW FORM */}
          <form
            onSubmit={submitReview}
            className="bg-zinc-900/70 border border-white/10 rounded-2xl p-10"
          >
            {/* NAME */}
            <input
              required
              placeholder="Your Name"
              className="w-full mb-5 px-5 py-3 rounded-lg bg-black border border-white/15 focus:border-[#e9b21a] outline-none"
              value={form.name}
              onChange={(e) =>
                setForm({ ...form, name: e.target.value })
              }
            />

            {/* STAR RATING */}
            <div className="flex items-center gap-3 mb-6">
              {[1, 2, 3, 4, 5].map((star) => (
                <button
                  type="button"
                  key={star}
                  onClick={() => setForm({ ...form, rating: star })}
                  className={`text-4xl transition ${
                    star <= form.rating
                      ? "text-[#e9b21a]"
                      : "text-gray-600 hover:text-gray-400"
                  }`}
                >
                  ★
                </button>
              ))}
            </div>

            {/* MESSAGE */}
            <textarea
              required
              rows="4"
              placeholder="Share your experience with Bodyzeal Fitworks..."
              className="w-full mb-6 px-5 py-3 rounded-lg bg-black border border-white/15 focus:border-[#e9b21a] outline-none resize-none"
              value={form.message}
              onChange={(e) =>
                setForm({ ...form, message: e.target.value })
              }
            />

            {/* SUBMIT */}
            <button
              type="submit"
              disabled={loading || form.rating === 0}
              className="w-full py-3 rounded-full bg-[#e9b21a] text-black font-semibold hover:bg-[#d4a318] transition"
            >
              {loading ? "Submitting..." : "Submit Review"}
            </button>

            {/* SUCCESS MESSAGE */}
            <AnimatePresence>
              {success && (
                <motion.p
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0 }}
                  className="mt-5 text-green-400 text-center text-sm"
                >
                  Thank you! Your review has been submitted.
                </motion.p>
              )}
            </AnimatePresence>
          </form>
        </motion.div>
      </div>

      {/* FOOTER */}
      <p className="mt-28 text-center text-sm text-gray-500 relative">
        © 2025 Bodyzeal Fitworks. All rights reserved.
      </p>
    </section>
  );
}
